#!/usr/bin/env node
/**
 * TRED — l'avertissement de suppression, et un peu de code mort.
 *
 *     node <chemin>\tred-suppression-claire.mjs
 *
 * 1. Le web disait "Dein Konto und alle Daten werden dauerhaft geloescht."
 *    Exact, mais vague. Le mobile, lui, enumere. Le web enumere maintenant
 *    aussi : compte, documents, conversations, semestres, exercices, credits,
 *    appareils, et "il n'y a pas de corbeille".
 *
 *    Le bouton exigeait deja le mot LOESCHEN et restait inerte sans lui : le
 *    garde-fou etait la, c'est l'information qui manquait.
 *
 * 2. useDeletionScope() retire de queries/account.ts. Je l'avais ecrit avec
 *    l'ecran Reglages ; aucun ecran ne l'appelle. La route serveur
 *    account.deletionScope reste — elle rend les noms de tables SQL, ce qui
 *    n'a rien a faire sous les yeux d'un etudiant.
 */
import { writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

function racine() {
  const departs = [process.cwd(), dirname(fileURLToPath(import.meta.url))];
  for (const depart of departs) {
    let d = depart;
    for (let i = 0; i < 8; i++) {
      if (existsSync(join(d, "packages", "web", "package.json"))) return d;
      const p = dirname(d);
      if (p === d) break;
      d = p;
    }
  }
  return null;
}

const ROOT = racine();
if (!ROOT) {
  console.error("\n  x  Depot introuvable.\n");
  process.exit(1);
}

const FILES = {
"packages/mobile/queries/account.ts": "",
"packages/web/src/web/i18n/messages/de.ts": "",
"packages/web/src/web/i18n/messages/en.ts": "",
"packages/web/src/web/i18n/messages/fr.ts": "",
"packages/web/src/web/i18n/messages/es.ts": ""
};
for (const [rel, b64] of Object.entries(FILES)) {
  const cible = join(ROOT, rel);
  mkdirSync(dirname(cible), { recursive: true });
  writeFileSync(cible, Buffer.from(b64, "base64"));
  console.log("  ecrit  " + rel);
}
console.log("\n  Les huit autres langues retombent sur l'allemand.\n");
